Object.assign(SNIP,{"rec_full": "// G[b][k]: diện tích lớn nhất của hình hợp lệ có đáy ở dòng b, cao không quá k\nvector<vector<int>> G(M, vector<int>(M + 1, 0));\nfor (int t = 0; t < 2; t++) {                       // t = 0: ô <= 1 là tốt; t = 1: ô >= 1 là tốt\n    vector<int> h(N, 0);\n    for (int b = 0; b < M; b++) {\n        for (int c = 0; c < N; c++) {\n            bool tot = (t == 0 ? a[b][c] <= 1 : a[b][c] >= 1);\n            h[c] = tot ? h[c] + 1 : 0;\n        }\n        vector<int> W(b + 2, 0), st;               // W[k]: dải cột rộng nhất có mọi h >= k\n        for (int c = 0; c <= N; c++) {\n            int cur = (c == N ? 0 : h[c]);          // cột lính canh cao 0\n            while (!st.empty() && h[st.back()] >= cur) {\n                int hh = h[st.back()];\n                st.pop_back();\n                int w = st.empty() ? c : c - st.back() - 1;\n                if (hh > 0) W[hh] = max(W[hh], w);\n            }\n            if (c < N) st.push_back(c);\n        }\n        for (int k = b; k >= 1; k--) W[k] = max(W[k], W[k + 1]);\n        int best = 0;\n        for (int k = 1; k <= b + 1; k++) {\n            best = max(best, k * W[k]);\n            G[b][k] = max(G[b][k], best);\n        }\n    }\n}\nvector<vector<int>> ans(M, vector<int>(M, 0));\nfor (int p = 0; p < M; p++)\n    for (int q = p; q < M; q++)\n        ans[p][q] = max(q > p ? ans[p][q - 1] : 0, G[q][q - p + 1]);", "abc_double": "long long kq = 0;                  // x, y kiểu double\nfor (int i = 0; i < n; i++) {\n    map<double, int> dem;           // khóa: hệ số góc; đường thẳng đứng ghi là 1e18\n    for (int j = i + 1; j < n; j++)\n        dem[x[j] == x[i] ? 1e18 : (y[j] - y[i]) / (x[j] - x[i])]++;\n    for (auto& p : dem) kq += 1LL * p.second * (p.second - 1) / 2;\n}", "twins_sang_duyet": "// đã sàng hop[] tới 10^6 một lần\nwhile (T--) {\n    int a, b;\n    cin >> a >> b;\n    long long s = 0;\n    int c = 0;\n    for (int x = a; x <= b; x++)    // vẫn duyệt cả đoạn cho từng câu hỏi\n        if (!hop[x]) {\n            s += x;\n            int r = 0, t = x;\n            while (t > 0) { r = r * 10 + t % 10; t /= 10; }\n            if (r != x && !hop[r]) c++;\n        }\n    cout << s << \" \" << c << \"\\n\";\n}", "door_bang2": "vector<vector<int>> dp(n + 1, vector<int>(S + 1, 0));   // (n + 1) x (S + 1) ô\ndp[0][0] = 1;\nfor (int i = 1; i <= n; i++)\n    for (long long s = 0; s <= S; s++) {\n        dp[i][s] = dp[i - 1][s];\n        if (s >= a[i - 1]) dp[i][s] = (dp[i][s] + dp[i - 1][s - a[i - 1]]) % MOD;\n    }\ncout << dp[n][S] << \"\\n\";", "door_full": "const long long MOD = 998244353;\n\nvector<long long> sinhTong(const vector<long long>& v) {   // mọi tổng tập con của v\n    vector<long long> r(1, 0);\n    for (long long x : v) {\n        int m = r.size();\n        for (int k = 0; k < m; k++) r.push_back(r[k] + x);\n    }\n    return r;\n}\n\n// trong main, sau khi đọc n, S, a:\nif (n <= 40) {                                  // gặp nhau ở giữa\n    vector<long long> L(a.begin(), a.begin() + n / 2), R(a.begin() + n / 2, a.end());\n    vector<long long> A = sinhTong(L), B = sinhTong(R);\n    sort(B.begin(), B.end());\n    long long kq = 0;\n    for (long long x : A)\n        kq += upper_bound(B.begin(), B.end(), S - x) - lower_bound(B.begin(), B.end(), S - x);\n    cout << kq % MOD << \"\\n\";\n} else {                                        // n > 40 thì n * S <= 5e7: QHĐ đếm\n    vector<long long> dp(S + 1, 0);\n    dp[0] = 1;\n    for (long long x : a)\n        for (long long s = S; s >= x; s--) dp[s] = (dp[s] + dp[s - x]) % MOD;\n    cout << dp[S] << \"\\n\";\n}", "twins_full": "const int MAX = 1000000;\nvector<bool> hop(MAX + 1, false);                   // hop[x] = true: x không nguyên tố\nhop[0] = hop[1] = true;\nfor (int i = 2; (long long)i * i <= MAX; i++)\n    if (!hop[i])\n        for (int j = i * i; j <= MAX; j += i) hop[j] = true;\nvector<long long> F(MAX + 1, 0);                    // F[x]: tổng số nguyên tố <= x\nvector<int> G(MAX + 1, 0);                          // G[x]: số số song sinh <= x\nfor (int x = 1; x <= MAX; x++) {\n    int d = 0;\n    if (!hop[x]) {\n        int r = 0, t = x;\n        while (t > 0) { r = r * 10 + t % 10; t /= 10; }\n        if (r != x && !hop[r]) d = 1;               // r <= 999999 nên luôn trong mảng\n    }\n    F[x] = F[x - 1] + (hop[x] ? 0 : x);\n    G[x] = G[x - 1] + d;\n}\nint T;\ncin >> T;\nwhile (T--) {\n    int a, b;\n    cin >> a >> b;\n    if (a < 1) a = 1;\n    cout << F[b] - F[a - 1] << \" \" << G[b] - G[a - 1] << \"\\n\";\n}", "abc_full": "long long kq = 0;\nfor (int i = 0; i < n; i++) {\n    vector<pair<long long, long long>> h;          // khóa: hướng từ điểm i tới điểm j > i\n    for (int j = i + 1; j < n; j++) {\n        long long dx = x[j] - x[i], dy = y[j] - y[i];\n        long long g = __gcd(abs(dx), abs(dy));      // g > 0 vì hai điểm khác nhau\n        dx /= g; dy /= g;\n        if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }\n        h.push_back({dx, dy});\n    }\n    sort(h.begin(), h.end());\n    for (int a = 0, b = 0; a < (int)h.size(); a = b) {\n        while (b < (int)h.size() && h[b] == h[a]) b++;\n        long long c = b - a;\n        kq += c * (c - 1) / 2;                      // c điểm cùng hướng: chọn 2\n    }\n}\ncout << kq << \"\\n\";", "rec_tung_p": "for (int p = 0; p < M; p++)              // M lần\n    for (int t = 0; t < 2; t++) {\n        vector<int> h(N, 0);\n        int best = 0;\n        for (int q = p; q < M; q++) {       // M lần\n            for (int c = 0; c < N; c++)     // N lần: cập nhật biểu đồ cột\n                h[c] = (t == 0 ? a[q][c] <= 1 : a[q][c] >= 1) ? h[c] + 1 : 0;\n            best = max(best, hinhLonNhat(h));   // ngăn xếp: thêm N bước\n            ans[p][q] = max(ans[p][q], best);\n        }\n    }", "abc_trau": "long long kq = 0;\nfor (int i = 0; i < n; i++)\n    for (int j = i + 1; j < n; j++)\n        for (int k = j + 1; k < n; k++)\n            if ((x[j] - x[i]) * (y[k] - y[i]) == (y[j] - y[i]) * (x[k] - x[i])) kq++;"});PRESET_NOTES["l34"]={"ABC: chuẩn hóa hướng từ một điểm": "Điểm (2, 2) và (−1, −1) nằm hai phía của gốc nhưng sau khi chia ƯCLN và chuẩn hóa dấu đều cho hướng (1, 1).", "TWINS: sàng và cộng dồn tới 40": "Sàng một lần, cộng dồn một lần; mỗi câu hỏi chỉ còn một phép trừ.", "DOOR: gặp nhau ở giữa với ví dụ của đề": "Nửa trái có 4 tổng {0, 1, 3, 4}, nửa phải có 8 tổng. Với mỗi tổng trái x, đếm số tổng phải bằng S − x.", "REC: ngăn xếp trên biểu đồ cột một dòng": "W[k] là bề rộng dải cột liên tiếp dài nhất có mọi chiều cao ≥ k. Đáp án cho dòng đáy này với chiều cao tối đa k là max j · W[j], j ≤ k."};EX_HINTS["l34"]=[["Subtask N = 3 (60% số điểm): chỉ một bộ ba, kiểm tra bằng tích có hướng (dùng long long).", "N ≤ 100: ba vòng lặp i < j < k."], ["Subtask T = 1 (4/7 điểm): duyệt đoạn, kiểm tra nguyên tố bằng chia thử tới căn bậc hai.", "Nhiều câu hỏi: sàng một lần, rồi mảng cộng dồn cho tổng và cho số lượng."], ["Subtask n ≤ 20 (3/5 điểm): duyệt mọi mặt nạ bit.", "Đọc kỹ ba subtask: mỗi test thuộc ít nhất một subtask, nên có thể rẽ nhánh theo n."], ["Subtask một cột (N = 1): mỗi truy vấn duyệt mọi đoạn dòng.", "Thử tay vài hình bị loại: chúng có điểm gì chung?"]];
