const PR34=[{label:"ABC: chuẩn hóa hướng từ một điểm",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint gcd2(int a, int b) { return b == 0 ? a : gcd2(b, a % b); }\n\nint main() {\n    int x[5] = {0, 2, -1, 1, 0}, y[5] = {0, 2, -1, 3, 4};\n    // đứng ở điểm 0 = (0, 0), nhìn 4 điểm còn lại\n    for (int j = 1; j < 5; j++) {\n        int dx = x[j] - x[0], dy = y[j] - y[0];\n        int g = gcd2(abs(dx), abs(dy));\n        dx /= g; dy /= g;\n        if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }\n        cout << \"diem \" << j << \": huong (\" << dx << \", \" << dy << \")\\n\";\n    }\n    // diem 1 va 2 cung huong (1, 1) du nam hai phia: 1 bo ba thang hang\n    return 0;\n}"},{label:"TWINS: sàng và cộng dồn tới 40",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    const int MAX = 40;\n    vector<bool> hop(MAX + 1, false);\n    hop[0] = hop[1] = true;\n    for (int i = 2; i * i <= MAX; i++)\n        if (!hop[i])\n            for (int j = i * i; j <= MAX; j += i) hop[j] = true;\n    vector<long long> F(MAX + 1, 0);\n    for (int x = 1; x <= MAX; x++) F[x] = F[x - 1] + (hop[x] ? 0 : x);\n    int a = 3, b = 13;\n    cout << \"tong so nguyen to trong [3, 13] = F[13] - F[2] = \" << F[b] - F[a - 1] << \"\\n\";\n    return 0;\n}"},{label:"DOOR: gặp nhau ở giữa với ví dụ của đề",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nvector<long long> sinhTong(vector<long long> v) {\n    vector<long long> r(1, 0);\n    for (long long x : v) {\n        int m = r.size();\n        for (int k = 0; k < m; k++) r.push_back(r[k] + x);\n    }\n    return r;\n}\n\nint main() {\n    long long S = 3;\n    vector<long long> L = {1, 3}, R = {2, 1, 1};     // dãy 1 3 2 1 1 cắt đôi\n    vector<long long> A = sinhTong(L), B = sinhTong(R);\n    sort(B.begin(), B.end());\n    long long kq = 0;\n    for (long long x : A) {\n        long long c = upper_bound(B.begin(), B.end(), S - x) - lower_bound(B.begin(), B.end(), S - x);\n        cout << \"trai = \" << x << \", can phai = \" << S - x << \": \" << c << \" cach\\n\";\n        kq += c;\n    }\n    cout << \"dap an = \" << kq << \"\\n\";\n    return 0;\n}"},{label:"REC: ngăn xếp trên biểu đồ cột một dòng",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> h = {2, 1, 3, 3, 0};                // chiều cao các cột ở một dòng đáy\n    int N = 4;\n    vector<int> W(5, 0), st;\n    for (int c = 0; c <= N; c++) {\n        int cur = (c == N ? 0 : h[c]);\n        while (!st.empty() && h[st.back()] >= cur) {\n            int hh = h[st.back()];\n            st.pop_back();\n            int w = st.empty() ? c : c - st.back() - 1;\n            if (hh > 0) W[hh] = max(W[hh], w);\n        }\n        if (c < N) st.push_back(c);\n    }\n    for (int k = 3; k >= 1; k--) W[k] = max(W[k], W[k + 1]);\n    for (int k = 1; k <= 3; k++) cout << \"cao \" << k << \": rong \" << W[k] << \", dien tich \" << k * W[k] << \"\\n\";\n    return 0;\n}"}];
